function UsageCharts(props){
          var points = props.points || [];
          var maxValue = Math.max.apply(null, points.map(function (point) { return point.total; }).concat([props.cap || 1100]));
          var width = 900;
          var height = 320;
          var stepX = points.length > 1 ? 760 / (points.length - 1) : 760;
          var capY = height - ((props.cap || maxValue) / maxValue) * 240 - 44;
          var path = points.map(function (point, index) {
            var x = 70 + index * stepX;
            var y = height - (point.total / maxValue) * 240 - 44;
            return (index === 0 ? "M" : "L") + x + " " + y;
          }).join(" ");
          var areaPath = path + " L " + String(70 + (points.length - 1) * stepX) + " " + String(height - 44) + " L 70 " + String(height - 44) + " Z";
          var hovered = points[uiState.usage.hoveredPointIndex == null ? points.length - 1 : uiState.usage.hoveredPointIndex] || null;
          var tooltip = hovered
            ? '<div class="shell-card" data-usage-tooltip="true" style="position:absolute; top:20px; right:24px; min-width:220px; z-index:3;"><strong>' + escapeHtml(hovered.label) + '</strong><div style="margin-top:6px; font-family:var(--font-serif); font-size:28px;">' + escapeHtml(formatMoney(hovered.total, uiState.locale)) + '</div><div style="margin-top:8px; display:flex; flex-direction:column; gap:6px;">' + Object.keys(hovered.byProvider).map(function (name) { return '<div style="display:flex; justify-content:space-between; gap:10px;"><span>' + escapeHtml(name) + '</span><strong>' + escapeHtml(formatMoney(hovered.byProvider[name], uiState.locale)) + "</strong></div>"; }).join("") + '</div></div>'
            : "";
          return (
            '<div data-usage-chart="true" style="position:relative; height:320px;">' +
              tooltip +
              '<svg viewBox="0 0 900 320" style="width:100%; height:320px; display:block;" aria-label="' + escapeHtml(localize(uiState.locale, "用量趋势图", "Usage trend chart")) + '">' +
                '<line x1="70" y1="' + String(capY) + '" x2="830" y2="' + String(capY) + '" stroke="var(--error)" stroke-dasharray="6 6"></line>' +
                '<text x="834" y="' + String(capY + 4) + '" fill="var(--error)" font-size="12">budget cap</text>' +
                '<path d="' + escapeHtml(areaPath) + '" fill="var(--accent-soft)"></path>' +
                '<path d="' + escapeHtml(path) + '" fill="none" stroke="var(--accent)" stroke-width="3"></path>' +
                '<line x1="70" y1="276" x2="830" y2="276" stroke="var(--border)"></line>' +
                points.map(function (point, index) {
                  var x = 70 + index * stepX;
                  var y = height - (point.total / maxValue) * 240 - 44;
                  return '<g data-usage-point-group="' + String(index) + '"><circle cx="' + String(x) + '" cy="' + String(y) + '" r="5" fill="' + escapeHtml(index === uiState.usage.hoveredPointIndex ? "var(--accent)" : "var(--bg-elevated)") + '" stroke="var(--accent)" stroke-width="2"></circle><text x="' + String(x - 10) + '" y="300" fill="var(--ink-3)" font-size="11">' + escapeHtml(index === 0 || index === points.length - 1 || index % Math.max(1, Math.floor(points.length / 6)) === 0 ? point.label : "") + '</text></g>';
                }).join("") +
              '</svg>' +
              '<div style="position:absolute; inset:0 56px 44px 70px; display:grid; grid-template-columns:repeat(' + String(points.length) + ', minmax(0, 1fr));">' +
                points.map(function (point, index) {
                  return '<button type="button" data-usage-point-index="' + String(index) + '" aria-label="' + escapeHtml(point.label + " " + formatMoney(point.total, uiState.locale)) + '" style="opacity:0; border:0; background:none; cursor:pointer;"></button>';
                }).join("") +
              '</div>' +
            '</div>'
          );
        }
